 * requirements_engine/evidence_level.py (BMW_SOURCES zählen mehr als Web, Web bestätigt nur,
 * Absatz/Optionsliste sind Kontext, kein Kundenbeleg). Keine neue Regel, nur die bestehende
 * für den Detailbildschirm sichtbar gemacht.
 */
const SOURCE_TRUST: Record<SourceType, { label: string; hint: string; className: string }> = {
  feedback: {
    label: "BMW customer data",
    hint: "Direct customer feedback; counts toward the evidence level.",
    className: "bg-emerald-50 text-emerald-700 border-emerald-300",
  },
  study: {
    label: "BMW customer data",
    hint: "BMW customer study; counts toward the evidence level.",
    className: "bg-emerald-50 text-emerald-700 border-emerald-300",
  },
  web: {
    label: "External · confirms only",
    hint: "Web source. Can confirm a finding but never carries it alone.",
    className: "bg-amber-50 text-amber-700 border-amber-300",
  },
  sales: {
    label: "Context data",
    hint: "Sales volume, not direct customer feedback.",
    className: "bg-zinc-50 text-zinc-600 border-zinc-300",
  },
  option_list: {
    label: "Context data",
    hint: "Today's options list, not direct customer feedback.",
    className: "bg-zinc-50 text-zinc-600 border-zinc-300",
  },
};

export function SourceTrustBadge({ sourceType }: { sourceType: SourceType }) {
  const style = SOURCE_TRUST[sourceType];
  return (
    <span
      title={style.hint}
      className={`inline-flex items-center rounded-full border px-2 py-0.5 text-xs font-medium ${style.className}`}
    >
      {style.label}
    </span>
  );
}

/**
 * Client-Teil der Detailseite (Ticket D3): holt GET /api/requirements/{id} und zeigt
 * Lade-/Fehlerzustand. `id` kommt als fertiger String vom Server-Wrapper
 * (app/requirements/[id]/page.tsx), damit dort `export const instant = false` stehen darf
 * (dieser Export braucht eine Server-Komponente, siehe Next 16 Cache Components).
 */
"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { getRequirementDetail, type Evidence, type RequirementDetail } from "@/src/lib/api";
import { RequirementDetailView } from "@/src/components/RequirementDetailView";

export function RequirementDetailPageClient({ id }: { id: string }) {
  const [detail, setDetail] = useState<RequirementDetail | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      setIsLoading(true);
      setError(null);
      try {
        const loaded = await getRequirementDetail(id);
        if (!cancelled) setDetail(loaded);
      } catch (err) {
        if (!cancelled) setError((err as Error).message);
      } finally {
        if (!cancelled) setIsLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [id]);

  // Belege je Befund vorsortieren, damit die Karten nicht bei jedem Render neu filtern.
  const evidenceBySignal = useMemo(() => {
    const byId = new Map<string, Evidence>();
    for (const item of detail?.evidence ?? []) byId.set(item.id, item);
    const bySignal = new Map<string, Evidence[]>();
    for (const signal of detail?.signals ?? []) {
      bySignal.set(
        signal.id,
        signal.evidence_ids.map((evId) => byId.get(evId)).filter((e): e is Evidence => Boolean(e)),
      );
    }
    return bySignal;
  }, [detail]);

  return (
    <div className="min-h-screen">
      <main className="mx-auto max-w-5xl px-6 py-8">
        <Link href="/" className="text-sm text-blue-600 hover:underline">
          ← Back to list
        </Link>

        {error && (
          <div className="mt-4 rounded-md border border-rose-300 bg-rose-50 px-4 py-3 text-sm text-rose-800">
            {error}
          </div>
        )}
        {!error && isLoading && <p className="mt-4 text-sm text-zinc-500">Loading…</p>}

        {!error && !isLoading && detail && (
          <>
            <RequirementDetailView detail={detail} evidenceBySignal={evidenceBySignal} />
            <div className="mt-8">
              <Link href="/" className="text-sm text-blue-600 hover:underline">
                ← Back to list
              </Link>
            </div>
          </>
        )}
      </main>
    </div>
  );
}

/**
 * Alle Abschnitte der Detailseite (Ticket D3) für eine bereits geladene Anforderung.
 * Eigene Datei, damit app/requirements/[id]/page.tsx nur Laden/Fehler regelt und beide
 * Dateien unter ~200 Zeilen bleiben (Jury-Review kappt danach).
 */
import type { Evidence, RequirementDetail } from "@/src/lib/api";
import { categoryLabel, EvidenceBadge, StatusBadge } from "@/src/components/badges";
import { ScoreWaterfall } from "@/src/components/ScoreWaterfall";
import { FindingCard } from "@/src/components/FindingCard";
import { AssumptionItem, OfferCheckBox } from "@/src/components/DetailBlocks";

export function RequirementDetailView({
  detail,
  evidenceBySignal,
}: {
  detail: RequirementDetail;
  evidenceBySignal: Map<string, Evidence[]>;
}) {
  const { requirement } = detail;

  return (
    <>
      <header className="mt-4">
        <div className="flex flex-wrap items-center gap-3">
          <h1 className="text-2xl font-semibold text-[#0b1f3a]">{requirement.title}</h1>
          <StatusBadge status={requirement.status} />
          <EvidenceBadge level={requirement.evidence_level} reason={requirement.rationale} />
        </div>
        <p className="mt-2 text-sm text-zinc-600">{requirement.rationale}</p>
        <p className="mt-1 text-xs text-zinc-400">
          {categoryLabel(requirement.category)} · Rank #{requirement.rank} · Effort {requirement.effort}
        </p>
      </header>

      <section className="mt-6">
        <h2 className="text-sm font-semibold uppercase tracking-wide text-zinc-500">Description</h2>
        <p className="mt-2 text-[#0b1f3a]">{requirement.description}</p>
      </section>

      <section className="mt-4 rounded-lg border-l-4 border-blue-600 bg-blue-50 p-4">
        <p className="text-xs font-semibold uppercase tracking-wide text-blue-700">
          Acceptance criterion
        </p>
        <p className="mt-1 text-[#0b1f3a]">{requirement.acceptance_criterion}</p>
      </section>

      <section className="mt-8">
        <ScoreWaterfall
          scoreBreakdown={requirement.score_breakdown}
          evidenceLevel={requirement.evidence_level}
          finalScore={requirement.score}
        />
      </section>

      <section className="mt-8 grid gap-6 md:grid-cols-2">
        <div className="rounded-lg border border-zinc-300 bg-white p-4">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-zinc-500">Evidence</h2>
          <div className="mt-3 space-y-3">
            {detail.signals.length === 0 && (
              <p className="text-sm text-zinc-400">No findings linked.</p>
            )}
            {detail.signals.map((signal) => (
              <FindingCard
                key={signal.id}
                signal={signal}
                evidence={evidenceBySignal.get(signal.id) ?? []}
              />
            ))}
          </div>
        </div>

        <div className="rounded-lg border-2 border-dashed border-zinc-300 bg-white p-4">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-zinc-500">
            Assumptions &amp; uncertainties
          </h2>
          <ul className="mt-3 space-y-2">
            {requirement.assumptions.map((text, i) => (
              <AssumptionItem key={`assumption-${i}`} label="Assumption" text={text} />
            ))}
            {requirement.uncertainties.map((text, i) => (
              <AssumptionItem key={`uncertainty-${i}`} label="Uncertainty" text={text} />
            ))}
            {requirement.assumptions.length === 0 && requirement.uncertainties.length === 0 && (
              <p className="text-sm text-zinc-400">No assumptions or uncertainties recorded.</p>
            )}
          </ul>
        </div>
      </section>

      <section className="mt-8">
        <OfferCheckBox offerCheck={requirement.offer_check} />
      </section>
    </>
  );
}

